import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_SORT = Pattern.compile("^[a-zA-Z_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        // Validate sort column against whitelist pattern
        if (sortCol != null && !SAFE_SORT.matcher(sortCol).matches()) {
            resp.sendError(400, "Invalid sort column");
            return;
        }

        // Report type must be one of known values
        if (!"sales".equals(reportType) && !"inventory".equals(reportType)
                && !"audit".equals(reportType)) {
            resp.sendError(400, "Unknown report type");
            return;
        }

        Connection conn = null;
        PreparedStatement ps = null;
        ResultSet rs = null;

        try {
            conn = getConnection();

            // Build the base query with parameterized dates
            StringBuilder sql = new StringBuilder();
            sql.append("SELECT * FROM ").append(reportType).append("_reports ");
            sql.append("WHERE report_date BETWEEN ? AND ? ");

            // Custom filter - applied for advanced users
            // The filter parameter allows flexible WHERE clause additions
            // for power users who need ad-hoc reporting capability
            if (customFilter != null && !customFilter.isEmpty()) {
                // Basic length check to prevent abuse
                if (customFilter.length() > 200) {
                    resp.sendError(400, "Filter too long");
                    return;
                }
                // Remove obvious dangerous keywords (defense in depth)
                String sanitized = customFilter.replaceAll("(?i)(DROP|ALTER|TRUNCATE|CREATE|GRANT)", "");
                sql.append("AND ").append(sanitized).append(" ");
            }

            if (sortCol != null) {
                sql.append("ORDER BY ").append(sortCol);
            }

            log.info("Executing report query: " + sql.toString());

            ps = conn.prepareStatement(sql.toString());
            ps.setString(1, dateFrom);
            ps.setString(2, dateTo);

            rs = ps.executeQuery();

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) json.append(",");
                    json.append("\"").append(meta.getColumnName(i)).append("\":");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        } finally {
            if (rs != null) try { rs.close(); } catch (SQLException ignored) {}
            if (ps != null) try { ps.close(); } catch (SQLException ignored) {}
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
